    private static final String CURRENT_SEGMENT_FIELD = "_currentSegment";
    private static final String MAX_SEGMENT_LEN_FIELD = "MAX_SEGMENT_LEN";

    @Before
    public void setUp() {
        recycler = new BufferRecycler();
        textBuffer = new TextBuffer(recycler);
    }

