        Field field = TextBuffer.class.getDeclaredField(MAX_SEGMENT_LEN_FIELD);
        field.setAccessible(true);
        return (int) field.get(null);
    }

    @Test
    public void testExpandCurrentSegment_StandardGrowth() throws Exception {
        // Setup: len = 10. 
        // len >> 1 = 5.
        // newLen = 10 / 5 = 2. 
        // Wait, the logic in the provided code is: int newLen = len / (len >> 1);
        // If len is 10, len >> 1 is 5. 10 / 5 = 2. This actually shrinks the buffer.
        // However, we must test the code as provided.

        char[] initial = new char[10];
        setCurrentSegment(initial);

        char[] expanded = textBuffer.expandCurrentSegment();

        // Calculation based on provided code:
        // len = 10
        // len >> 1 = 5
        // newLen = 10 / 5 = 2
        Assert.assertEquals(2, expanded.length);

        // Verify the internal reference is updated
        char[] internal = textBuffer.getCurrentSegment();
        Assert.assertSame(expanded, internal);
    }






}

